<script setup>
import { ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(),router=useRouter(),route=useRoute(),mode=ref('login'),loading=ref(false),error=ref('')
const form=ref({fullName:'',email:'',password:'',passwordRepeat:'',role:'customer'})
async function submit(){error.value='';if(mode.value==='register'&&form.value.password!==form.value.passwordRepeat){error.value='Пароли не совпадают';return}loading.value=true;try{if(mode.value==='login')await auth.signIn({email:form.value.email,password:form.value.password});else await auth.register({fullName:form.value.fullName,email:form.value.email,password:form.value.password});router.push(route.query.redirect||'/')}catch(e){error.value=e.message||'Не удалось выполнить запрос. Проверьте введённые данные.'}finally{loading.value=false}}
function switchMode(value){mode.value=value;error.value=''}
</script>
<template><main class="auth-page"><section class="auth-intro"><RouterLink class="brand auth-brand" to="/"><span class="brand-mark">◈</span><span>Поверка<span class="brand-dot">.pro</span></span></RouterLink><div class="intro-copy"><span class="intro-badge">ИНФОРМАЦИОННАЯ СИСТЕМА</span><h1>Контроль поверок<br><em>без лишних рисков.</em></h1><p>Единый реестр средств измерений, планирование поверок и своевременные уведомления для предприятия.</p><div class="intro-points"><span>✓ Контроль сроков в реальном времени</span><span>✓ Прозрачная история каждого прибора</span><span>✓ Готовые отчёты для аудита</span></div></div><small>© 2026 Поверка.pro</small></section><section class="auth-form-area"><form class="auth-card" @submit.prevent="submit"><div class="auth-tabs"><button type="button" :class="{selected:mode==='login'}" @click="switchMode('login')">Вход</button><button type="button" :class="{selected:mode==='register'}" @click="switchMode('register')">Регистрация</button></div><div class="auth-heading"><h2>{{mode==='login'?'С возвращением!':'Создайте аккаунт'}}</h2><p>{{mode==='login'?'Введите данные для входа в рабочее пространство.':'Выберите роль и зарегистрируйтесь в системе.'}}</p></div><label v-if="mode==='register'" class="field">Ваше имя<input v-model.trim="form.fullName" required autocomplete="name" placeholder="Иван Иванов"></label><label v-if="mode==='register'" class="field">Роль<select v-model="form.role"><option value="customer">Заказчик</option><option value="engineer">Инженер-лаборант</option></select></label><label class="field">Электронная почта<input v-model.trim="form.email" required type="email" autocomplete="email" placeholder="name@company.ru"></label><label class="field">Пароль<input v-model="form.password" required minlength="6" type="password" autocomplete="current-password" placeholder="Минимум 6 символов"></label><label v-if="mode==='register'" class="field">Повторите пароль<input v-model="form.passwordRepeat" required minlength="6" type="password" autocomplete="new-password" placeholder="Повторите пароль"></label><p v-if="error" class="auth-error">{{error}}</p><button class="auth-submit" :disabled="loading">{{loading?'Подождите…':mode==='login'?'Войти в систему':'Зарегистрироваться'}} <span>→</span></button><p class="auth-foot">{{mode==='login'?'Нет учётной записи?':'Уже есть учётная запись?'}} <button type="button" @click="switchMode(mode==='login'?'register':'login')">{{mode==='login'?'Зарегистрироваться':'Войти'}}</button></p></form></section></main></template>
